input.content:
/**
 * fall-detector.js - 两阶段跌倒 / 异常静止检测状态机
 *
 * 解决"4 秒窗口单次命中即告警"导致的高误报：
 *
 *   跌倒：阶段一捕获"冲击峰值"只标记候选，不告警；
 *         阶段二要求冲击后"持续静止"达到阈值时长才确认。
 *         期间只要佩戴者恢复明显运动（起身、甩手、继续走）
 *         就立刻取消候选，从而抑制"猛坐下/跳跃/磕手腕/摘表"
 *         等冲击型误报。
 *
 *   异常静止：不再用 4 秒低活动判定，而是要求"曾出现过活动
 *          → 之后持续低活动"达到更长时间（30s）才上报，
 *          避免把"一直静止佩戴"当成异常。
 *
 * 与 fall-model.js 的 12 维决策树配合：本状态机决定"何时触发"，
 * 决策树在触发时提供特征证据（见 home.ux buildResultFor）。
 *
 * 可选 options：
 *   stillMs       跌倒确认所需静止时长（默认 8000，回放演示可调短）
 *   immobilityMs  异常静止所需低活动时长（默认 30000）
 *   onState       状态迁移回调 onState(type, detail)，用于可视化
 *                 type ∈ candidate | cancelled | fall | immobility
 */

function magnitude(x, y, z) {
  return Math.sqrt(x * x + y * y + z * z)
}

function variance(values) {
  if (!values.length) { return 0 }
  var avg = 0
  var i
  for (i = 0; i < values.length; i++) { avg += values[i] }
  avg = avg / values.length
  var total = 0
  for (i = 0; i < values.length; i++) {
    var d = values[i] - avg
    total += d * d
  }
  return total / values.length
}

// 阈值（真机采样频率下的经验值）
var IMPACT_PEAK_G = 2.5      // 冲击峰值（g）
var MOVE_G = 1.6             // 候选期间超过此值视为恢复运动
var STILL_VAR = 0.05         // 冲击后静止方差阈值
var STILL_MS = 8000          // 跌倒确认需要的持续静止时长（默认）
var IMMOBILITY_VAR = 0.02    // 低活动方差阈值
var IMMOBILITY_MS = 30000    // 异常静止需要的持续低活动时长（默认）
var COOLDOWN_MS = 30000      // 两次事件之间的冷却
var ACTIVE_VAR = 0.05        // 判定"曾有过活动"的方差阈值
var ACTIVITY_WINDOW = 40     // 活动窗样本数

export function createFallDetector(options) {
  options = options || {}
  var stillMs = options.stillMs || STILL_MS
  var immobilityMs = options.immobilityMs || IMMOBILITY_MS
  var onState = options.onState || function() {}

  var state = "idle"         // idle | candidate
  var pre = []               // 冲击前短窗（g 值，找失重下限）
  var post = []              // 冲击后静止窗（g 值）
  var candidateAt = 0
  var candidatePeakG = 0
  var candidateMinG = 0
  var lastConfirmAt = 0
  var lastNow = 0

  var stillSince = 0         // 持续低活动起始时间
  var hadActivity = false    // 是否曾出现过明显活动
  var activityWindow = []    // 短窗，用于当前低活动 & 曾否活动判定

  function resetFall() {
    state = "idle"
    pre = []
    post = []
  }

  function push(sample) {
    var g = magnitude(sample.x || 0, sample.y || 0, sample.z || 0)
    var now = sample.timestamp || Date.now()
    lastNow = now
    var cooldownOk = now - lastConfirmAt >= COOLDOWN_MS

    // ── 活动窗维护（供异常静止使用）──
    activityWindow.push(g)
    if (activityWindow.length > ACTIVITY_WINDOW) { activityWindow.shift() }
    if (activityWindow.length >= 20) {
      if (variance(activityWindow) > ACTIVE_VAR) { hadActivity = true }
    }

    // ── 跌倒：冲击候选 → 持续静止确认 ──
    if (state === "idle") {
      pre.push(g)
      if (pre.length > 20) { pre.shift() }
      if (g >= IMPACT_PEAK_G) {
        state = "candidate"
        candidateAt = now
        candidatePeakG = g
        candidateMinG = pre[0]
        for (var m = 1; m < pre.length; m++) {
          if (pre[m] < candidateMinG) { candidateMinG = pre[m] }
        }
        post = []
        onState("candidate", { peakG: candidatePeakG, minG: candidateMinG })
      }
    } else {
      // candidate
      if (g > MOVE_G) {
        var cancelledPeak = candidatePeakG
        resetFall()                       // 恢复运动 → 取消候选
        onState("cancelled", { peakG: cancelledPeak })
      } else {
        post.push(g)
        if (g > candidatePeakG) { candidatePeakG = g }
        var stillDur = now - candidateAt
        if (post.length >= 10 && variance(post.slice(-30)) <= STILL_VAR && stillDur >= stillMs) {
          resetFall()
          if (cooldownOk) {
            lastConfirmAt = now
            stillSince = 0
            var hit = {
              type: "fall",
              confidence: 0.9,
              at: now,
              stillMs: stillDur,
              peakG: candidatePeakG,
              minG: candidateMinG
            }
            onState("fall", hit)
            return hit
          }
        }
      }
    }

    // ── 异常静止：曾活动 → 持续低活动 ──
    if (hadActivity && activityWindow.length >= 20 && variance(activityWindow) <= IMMOBILITY_VAR) {
      if (stillSince === 0) { stillSince = now }
      var immDur = now - stillSince
      if (immDur >= immobilityMs && cooldownOk) {
        lastConfirmAt = now
        stillSince = 0
        hadActivity = false
        var immHit = { type: "immobility", confidence: 0.9, at: now, stillMs: immDur }
        onState("immobility", immHit)
        return immHit
      }
    } else {
      stillSince = 0
    }

    return null
  }

  function getState() {
    return {
      state: state,
      stillMs: state === "candidate" ? (lastNow - candidateAt) : 0,
      peakG: candidatePeakG,
      hadActivity: hadActivity
    }
  }

  return {
    push: push,
    reset: resetFall,
    getState: getState
  }
}

