// 长按 SOS：2 秒倒计时按压反馈，期间按钮变色并显示剩余秒数
triggerSosLong() {
  var page = this
  if (this.sosCounting) { return }
  this.sosCounting = true
  this.sosLabel = "2"
  this.sosClass = "sos-btn sos-round sos-armed"
  this.sosTimer = setInterval(function() {
    if (page.sosLabel === "2") {
      page.sosLabel = "1"
    } else {
      page.resetSosButton()
      page.openAlert(createSosAlert())
    }
  }, 1000)
},

resetSosButton() {
  if (this.sosTimer) { clearInterval(this.sosTimer); this.sosTimer = null }
  this.sosCounting = false
  this.sosLabel = "SOS"
  this.sosClass = "sos-btn sos-round"
},

