/**
 * watch-face.js - 表盘形状检测、安全区计算与字体缩放
 *
 * 圆形表盘使用内接正方形作为内容安全区，保证四角不被圆弧裁切。
 * 形状检测优先走 @system.device.getInfo()（screenWidth/screenHeight/
 * screenShape[rect|circle|pill-shaped]/screenDensity），异步结果覆盖；
 * 同步阶段先用 DEVICE_PROFILE 兜底（目标模拟器 466×466 正圆）。
 */

import device from "@system.device"

var screenW = 0
var screenH = 0
var shapeCache = null

// 目标设备表盘参数（模拟器：466×466 物理像素、正圆）。
// CSS 1px = 1 物理像素（manifest designWidth: "device-width"），见 vela-watch-device-units。
var DEVICE_PROFILE = {
  screenWidth: 466,
  screenHeight: 466,
  shape: "circle"
}

// getInfo() 成功返回的设备信息（覆盖 profile）
var deviceInfo = null
var refreshDone = false
var refreshCbs = []

function detectShape() {
  var width = DEVICE_PROFILE.screenWidth
  var height = DEVICE_PROFILE.screenHeight
  var explicitShape = DEVICE_PROFILE.shape

  if (deviceInfo) {
    width = deviceInfo.screenWidth || width
    height = deviceInfo.screenHeight || height
    if (deviceInfo.screenShape) { explicitShape = deviceInfo.screenShape }
    else if (deviceInfo.shape) { explicitShape = deviceInfo.shape }
  }

  screenW = width
  screenH = height

  var isRound = false
  if (explicitShape === "circle" || explicitShape === "round") {
    isRound = true
  } else if (explicitShape === "rect" || explicitShape === "square" || explicitShape === "pill-shaped") {
    isRound = false
  } else {
    var ratio = screenW / screenH
    isRound = ratio > 0.9 && ratio < 1.1
  }

  shapeCache = {
    isRound: isRound,
    isSquare: !isRound,
    screenWidth: screenW,
    screenHeight: screenH
  }
  return shapeCache
}

// ─── 形状检测 ──────────────────────────────────────────

export function getScreenShape() {
  if (!shapeCache) { detectShape() }
  return shapeCache
}

export function getScreenHeight() {
  return getScreenShape().screenHeight
}

// 异步拉取真实设备信息，覆盖 466 兜底后回调（供页面 re-compute 样式）。
export function refreshScreenShape(cb) {
  if (cb) { refreshCbs.push(cb) }
  if (refreshDone) { return }
  refreshDone = true

  function fire() {
    for (var i = 0; i < refreshCbs.length; i++) { refreshCbs[i](getScreenShape()) }
    refreshCbs = []
  }

  try {
    device.getInfo({
      success: function(info) {
        deviceInfo = info || null
        shapeCache = null
        detectShape()
        fire()
      },
      fail: function() { fire() }
    })
  } catch (e) { fire() }
}

// ─── 安全区内边距 ────────────────────────────────────

export function getSafePadding() {
  var shape = getScreenShape()
  if (shape.isRound) {
    // 圆内接正方形：边长 = D·√2/2 ≈ 0.707D，四周留白 = (D-边长)/2 ≈ 0.1465D。
    // 内容为居中列时四角不会触边，保证不被圆弧裁切。
    var diameter = Math.min(shape.screenWidth, shape.screenHeight)
    var pad = Math.round(((1 - 0.7071) / 2) * diameter)
    return { top: pad, right: pad, bottom: pad, left: pad }
  }
  return { top: 18, right: 18, bottom: 16, left: 18 }
}

// ─── 内容列最大宽度（圆形=内接正方形边长，方形=全宽减内边距） ──

export function getContentWidth() {
  var shape = getScreenShape()
  if (shape.isRound) {
    return Math.round(Math.min(shape.screenWidth, shape.screenHeight) * 0.7071)
  }
  return shape.screenWidth - 36
}

// ─── 内容 padding（圆形安全区） ───────────────────────

export function getContentPadding() {
  var p = getSafePadding()
  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
}

// ─── 圆角 ────────────────────────────────────────────

export function getCardRadius() {
  return getScreenShape().isRound ? 26 : 20
}

export function getButtonRadius() {
  return getScreenShape().isRound ? 24 : 23
}

// ─── 字体缩放 ──────────────────────────────────────────

export function getFontScale() {
  return getScreenShape().isRound ? 1.15 : 1.0
}

export function fs(baseSize) {
  var scale = getFontScale()
  return Math.round(baseSize * scale)
}

// ─── 按钮高度缩放 ──────────────────────────────────────

export function getButtonHeight(base) {
  return getScreenShape().isRound ? Math.round(base * 1.15) : base
}

// ─── 卡片是否使用竖向布局 ────────────────────────────

export function useVerticalLayout() {
  return getScreenShape().isRound
}

// ─── 动态 padding 字符串 ──────────────────────────────

export function padStr() {
  var p = getSafePadding()
  return p.top + "px " + p.right + "px " + p.bottom + "px " + p.left + "px"
}

