/**
 * watch-face.js - 表盘形状检测、安全区计算与字体缩放
 *
 * 圆形表盘使用内接正方形作为内容安全区，保证四角不被圆弧裁切。
 * 布局尺寸（dp）恒用 DEVICE_PROFILE（目标设备固定 466×466 圆屏 = 233dp）；
 * @system.device.getInfo() 仅用于校正形状（screenShape），
 * 不使用其 screenWidth/screenHeight/screenDensity 数值（换算不可靠，见 vela-watch-device-units）。
 */

import device from "@system.device"

var screenW = 0
var screenH = 0
var shapeCache = null

// 目标设备表盘参数：466×466 物理像素、density 320（DPR=2.0）、正圆。
// manifest designWidth: "device-width" 下 CSS 1px = 1dp，
// 故布局尺寸 = 466 / 2.0 = 233dp（见 vela-watch-device-units）。
// 注意：getInfo() 返回的 screenWidth/Height 是物理像素，screenDensity 是原始 dpi，
// 其换算在个别固件上不可靠，故布局尺寸只信任 DEVICE_PROFILE，getInfo 仅用于判形状。
var DEVICE_PROFILE = {
  screenWidth: 233,
  screenHeight: 233,
  shape: "circle"
}

if (deviceInfo) {
  // 只读取形状：getInfo() 的 screenWidth/Height 是物理像素、screenDensity 是原始 dpi，
  // 与 dp 的换算在个别固件上不可靠（除以 320 会把布局塌缩到 ~1.5px）。
  // 目标设备固定 466×466/density320(DPR2.0) 圆屏，布局尺寸恒用 DEVICE_PROFILE(233dp)。
  if (deviceInfo.screenShape) { explicitShape = deviceInfo.screenShape }
  else if (deviceInfo.shape) { explicitShape = deviceInfo.shape }
}

